/**
 * Demo Mode.
 *
 * Loads the bundled sample repo (four planted bugs) and merges cached model
 * responses. It makes no network calls at all, so the demo works on bad Wi-Fi
 * or with no model running.
 *
 * The cached responses live in demo/cache and are regenerated by
 * `npx tsx scripts/build-demo-cache.mts`.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { config } from '../config.js';
import type { Finding, RepoFile, RepoSummary, ScanResult, Severity } from '../types.js';
import { runScan } from '../scan/engine.js';
import { mechanicalFix } from '../patch/mechanical.js';
import type { JobContext } from '../jobs.js';
import { redactSecrets } from '../redaction.js';

const noopContext: JobContext = {
  id: 'demo',
  signal: new AbortController().signal,
  step: () => {},
  progress: () => {},
  checkpoint: () => {},
};

export interface CachedFinding {
  file: string;
  line: number;
  severity: Severity;
  confidence: number;
  title: string;
  explanation: string;
  whyItMatters: string;
  category: string;
}

export interface CachedFix {
  summary: string;
  testPlan: string;
  prTitle: string;
  diff: string;
}

interface DemoCache {
  findings: { version: number; model: string; findings: CachedFinding[] };
  fixes: { version: number; model: string; fixes: Record<string, CachedFix> };
  issues: {
    version: number;
    issues: Array<{ number: number; title: string; body: string; htmlUrl: string; labels: string[] }>;
  };
}

export interface DemoBundle {
  repo: RepoSummary;
  scan: ScanResult;
  files: RepoFile[];
}

export const DEMO_REPO: RepoSummary = {
  owner: 'bugbanisher-demo',
  name: 'moonlit-mailroom',
  fullName: 'bugbanisher-demo/moonlit-mailroom',
  private: false,
  archived: false,
  fork: false,
  defaultBranch: 'main',
  description: 'Bundled sample service with four deliberately planted bugs (offline Demo Mode).',
  language: 'JavaScript',
  stars: 0,
  updatedAt: null,
  // Deliberately empty: there is no GitHub repository to link to in Demo Mode.
  htmlUrl: '',
};

function readJson<T>(file: string): T {
  const full = path.join(config.demoDir, 'cache', file);
  return JSON.parse(fs.readFileSync(full, 'utf8')) as T;
}

export function loadCache(): DemoCache {
  return {
    findings: readJson<DemoCache['findings']>('findings.json'),
    fixes: readJson<DemoCache['fixes']>('fixes.json'),
    issues: readJson<DemoCache['issues']>('issues.json'),
  };
}

/** Read the sample repo from disk. Only used by Demo Mode. */
export function loadSampleRepo(): { paths: string[]; files: RepoFile[] } {
  const root = path.join(config.demoDir, 'sample-repo');
  const paths: string[] = [];
  const files: RepoFile[] = [];

  const walk = (dir: string) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
        continue;
      }
      const rel = path.relative(root, full).split(path.sep).join('/');
      paths.push(rel);
      const content = fs.readFileSync(full, 'utf8');
      files.push({ path: rel, content, size: content.length });
    }
  };

  walk(root);
  return { paths, files };
}

/** Attach the cached model findings to the real static scan of the sample repo. */
function mergeCachedFindings(scan: ScanResult, cached: CachedFinding[]): Finding[] {
  const findings = scan.findings.map((finding) => ({ ...finding }));
  const consumed = new Set<number>();

  for (const reply of cached) {
    const matchIndex = findings.findIndex(
      (finding, index) =>
        !consumed.has(index) &&
        finding.file === reply.file &&
        Math.abs(finding.line - reply.line) <= 3,
    );

    if (matchIndex === -1) {
      findings.push({
        id: `llm-demo-${reply.file}-${reply.line}`,
        source: 'llm',
        file: reply.file,
        line: reply.line,
        severity: reply.severity,
        confidence: reply.confidence,
        title: reply.title,
        explanation: redactSecrets(reply.explanation),
        whyItMatters: redactSecrets(reply.whyItMatters),
        ruleId: `llm/${reply.category}`,
      });
      continue;
    }

    consumed.add(matchIndex);
    const existing = findings[matchIndex];
    if (!existing) continue;
    findings[matchIndex] = {
      ...existing,
      source: 'static+llm',
      severity: reply.severity,
      confidence: Math.max(existing.confidence, reply.confidence),
      title: reply.title,
      explanation: redactSecrets(reply.explanation),
      whyItMatters: redactSecrets(reply.whyItMatters),
    };
  }

  const weight: Record<Severity, number> = { high: 3, medium: 2, low: 1 };
  return findings.sort((a, b) => weight[b.severity] - weight[a.severity] || b.confidence - a.confidence);
}

export async function buildDemoBundle(): Promise<DemoBundle> {
  const cache = loadCache();
  const { paths, files } = loadSampleRepo();

  const scan = await runScan(
    { token: '', repo: DEMO_REPO, mode: 'demo', localFiles: files, localPaths: paths },
    noopContext,
  );

  const merged = mergeCachedFindings(scan, cache.findings.findings);

  // The bundled open issue is evidence for the off-by-one bug.
  for (const issue of cache.issues.issues) {
    merged.push({
      id: `issue-${issue.number}`,
      source: 'issue',
      file: `issue #${issue.number}`,
      line: 0,
      severity: 'medium',
      confidence: 45,
      title: issue.title,
      explanation: redactSecrets(issue.body),
      whyItMatters:
        'Open bug issues are real-world evidence: someone already hit this. Closing the loop with a tested fix is how a small project earns trust.',
      ruleId: 'issue/bug',
      issue: { number: issue.number, title: issue.title, url: issue.htmlUrl, labels: issue.labels },
    });
  }

  // Keep the "fixable now" flags accurate after cached findings are merged in.
  for (const finding of merged) {
    const file = files.find((candidate) => candidate.path === finding.file);
    finding.autoFixAvailable =
      finding.source !== 'issue' && finding.line > 0 && file
        ? mechanicalFix(finding, file.content) !== null
        : false;
  }

  const notes = [
    'Demo Mode: bundled sample repo and cached model responses. No network calls were made.',
    'Nothing in Demo Mode is ever written to GitHub.',
    ...scan.notes.filter((note) => !note.includes('Model review skipped')),
  ];

  return {
    repo: DEMO_REPO,
    files,
    scan: {
      ...scan,
      // Stable id: the bundle is deterministic, so any instance (or a later
      // request on a serverless cold start) can rebuild the exact same scan.
      scanId: demoScanId(merged.map((finding) => finding.id)),
      findings: merged,
      stats: {
        ...scan.stats,
        issuesRead: cache.issues.issues.length,
        modelUsed: `${cache.findings.model} (cached)`,
        modelAvailable: true,
        autoFixableCount: merged.filter((finding) => finding.autoFixAvailable).length,
      },
      notes,
      createdAt: new Date().toISOString(),
    },
  };
}

/** Deterministic demo scan id, derived from the findings it contains. */
export function demoScanId(findingIds: string[]): string {
  const hash = crypto.createHash('sha256').update(findingIds.join('|')).digest('hex');
  return `demo-${hash.slice(0, 16)}`;
}

export function cachedFixFor(findingId: string): CachedFix | null {
  const cache = loadCache();
  return cache.fixes.fixes[findingId] ?? null;
}

export function cachedModelName(): string {
  return loadCache().fixes.model;
}
